_elementor_page_settings.custom_css:
/* ===================================================
   PÁGINA DE PERSONAJES: ARQUITECTURA VISUAL EDITORIAL 2026
   =================================================== */

/* Ocultar elementos heredados redundantes */
html body .elementor-element-42f2bb7,
html body [data-id="42f2bb7"],
html body .elementor-element-c5b2b13,
html body [data-id="c5b2b13"],
html body .elementor-element-7587280,
html body [data-id="7587280"] {
    display: none !important;
}

/* Contenedor principal con fondo cálido de revista */
html body .elementor-element-31b56d1,
html body [data-id="31b56d1"] {
    background-color: #F9F7F2 !important;
    padding: 3.5rem 1.5rem 5rem 1.5rem !important;
    max-width: 1400px !important;
    margin: 0 auto !important;
    width: 100% !important;
    box-sizing: border-box !important;
}

/* Rejilla de tarjetas de personajes */
html body .elementor-element-71c0232 .elementor-posts-container,
html body [data-id="71c0232"] .elementor-posts-container {
    display: grid !important;
    grid-template-columns: repeat(3, 1fr) !important;
    gap: 1.75rem !important;
    width: 100% !important;
}

/* Tarjeta individual */
html body .elementor-element-71c0232 .elementor-post,
html body [data-id="71c0232"] .elementor-post {
    background: #FFFFFF !important;
    border-radius: 18px !important;
    border: 1px solid rgba(22, 28, 34, 0.08) !important;
    overflow: hidden !important;
    box-shadow: 0 4px 18px rgba(30, 37, 43, 0.04) !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: space-between !important;
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s ease !important;
}
html body .elementor-element-71c0232 .elementor-post:hover,
html body [data-id="71c0232"] .elementor-post:hover {
    transform: translateY(-6px) !important;
    box-shadow: 0 16px 36px rgba(30, 37, 43, 0.1) !important;
    border-color: rgba(164, 60, 27, 0.3) !important;
}

/* Enlace del Thumbnail: bloque completo sin márgenes */
html body .elementor-element-71c0232 .elementor-post__thumbnail__link,
html body [data-id="71c0232"] .elementor-post__thumbnail__link {
    display: block !important;
    width: 100% !important;
    max-width: 100% !important;
    position: relative !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    border-radius: 18px 18px 0 0 !important;
}

/* Contenedor del Thumbnail: Altura uniforme de 230px, anula padding-bottom de Elementor */
html body .elementor-element-71c0232 .elementor-posts-container .elementor-post__thumbnail,
html body .elementor-element-71c0232 .elementor-post__thumbnail,
html body [data-id="71c0232"] .elementor-post__thumbnail {
    display: block !important;
    width: 100% !important;
    max-width: 100% !important;
    height: 230px !important;
    min-height: 230px !important;
    max-height: 230px !important;
    padding: 0 !important;
    padding-bottom: 0 !important;
    margin: 0 !important;
    position: relative !important;
    overflow: hidden !important;
    background: transparent !important;
    background-color: transparent !important;
    border-radius: 18px 18px 0 0 !important;
}

/* Imagen de Portada: Llena el 100% a sangre (full-bleed) de 230px con object-fit cover */
html body .elementor-element-71c0232 .elementor-posts-container .elementor-post__thumbnail img,
html body .elementor-element-71c0232 .elementor-post__thumbnail img,
html body [data-id="71c0232"] .elementor-post__thumbnail img,
html body .elementor-element-71c0232 img.attachment-1536x1536,
html body [data-id="71c0232"] img {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    width: 100% !important;
    min-width: 100% !important;
    max-width: 100% !important;
    height: 100% !important;
    min-height: 100% !important;
    max-height: 100% !important;
    transform: none !important;
    object-fit: cover !important;
    object-position: center center !important;
    display: block !important;
    border-radius: 18px 18px 0 0 !important;
    transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

html body .elementor-element-71c0232 .elementor-post:hover .elementor-post__thumbnail img,
html body [data-id="71c0232"] .elementor-post:hover .elementor-post__thumbnail img {
    transform: scale(1.05) !important;
}

/* Textos de la tarjeta */
html body .elementor-element-71c0232 .elementor-post__text,
html body [data-id="71c0232"] .elementor-post__text {
    padding: 1.45rem 1.4rem 1.5rem 1.4rem !important;
    display: flex !important;
    flex-direction: column !important;
    flex-grow: 1 !important;
}

html body .elementor-element-71c0232 .elementor-post__meta-data,
html body [data-id="71c0232"] .elementor-post__meta-data {
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.72rem !important;
    font-weight: 800 !important;
    color: #A43C1B !important;
    text-transform: uppercase !important;
    letter-spacing: 0.08em !important;
    margin-bottom: 0.55rem !important;
}

html body .elementor-element-71c0232 .elementor-post__title,
html body [data-id="71c0232"] .elementor-post__title {
    font-family: 'Playfair Display', serif !important;
    font-size: 1.25rem !important;
    font-weight: 700 !important;
    line-height: 1.35 !important;
    margin: 0 0 0.7rem 0 !important;
}

html body .elementor-element-71c0232 .elementor-post__title a,
html body [data-id="71c0232"] .elementor-post__title a {
    color: #151C22 !important;
    text-decoration: none !important;
    transition: color 0.2s ease !important;
}

html body .elementor-element-71c0232 .elementor-post__title a:hover,
html body [data-id="71c0232"] .elementor-post__title a:hover {
    color: #A43C1B !important;
}

html body .elementor-element-71c0232 .elementor-post__excerpt p,
html body [data-id="71c0232"] .elementor-post__excerpt p {
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.88rem !important;
    color: #555555 !important;
    line-height: 1.55 !important;
    margin: 0 0 1.2rem 0 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 3 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
}

html body .elementor-element-71c0232 .elementor-post__read-more,
html body [data-id="71c0232"] .elementor-post__read-more {
    margin-top: auto !important;
    color: #A43C1B !important;
    font-weight: 700 !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.88rem !important;
    text-decoration: none !important;
    display: inline-flex !important;
    align-items: center !important;
    gap: 6px !important;
    transition: gap 0.2s ease !important;
}

html body .elementor-element-71c0232 .elementor-post__read-more:hover,
html body [data-id="71c0232"] .elementor-post__read-more:hover {
    gap: 10px !important;
    color: #7B2E15 !important;
}

/* Paginación Elegante */
html body .elementor-element-71c0232 .elementor-pagination,
html body [data-id="71c0232"] .elementor-pagination {
    margin-top: 3.5rem !important;
    display: flex !important;
    justify-content: center !important;
    gap: 8px !important;
}

html body .elementor-element-71c0232 .elementor-pagination .page-numbers,
html body [data-id="71c0232"] .elementor-pagination .page-numbers {
    padding: 9px 16px !important;
    border-radius: 8px !important;
    border: 1.5px solid rgba(22, 28, 34, 0.12) !important;
    background: #FFFFFF !important;
    color: #151C22 !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.92rem !important;
    font-weight: 700 !important;
    text-decoration: none !important;
    transition: all 0.2s ease !important;
}

html body .elementor-element-71c0232 .elementor-pagination .page-numbers:hover,
html body [data-id="71c0232"] .elementor-pagination .page-numbers:hover {
    border-color: #151C22 !important;
    background: #151C22 !important;
    color: #FFFFFF !important;
}

html body .elementor-element-71c0232 .elementor-pagination .page-numbers.current,
html body [data-id="71c0232"] .elementor-pagination .page-numbers.current {
    background: #A43C1B !important;
    color: #FFFFFF !important;
    border-color: #A43C1B !important;
}

@media (max-width: 1024px) {
    html body .elementor-element-71c0232 .elementor-posts-container,
    html body [data-id="71c0232"] .elementor-posts-container {
        grid-template-columns: repeat(2, 1fr) !important;
    }
}

@media (max-width: 640px) {
    html body .elementor-element-71c0232 .elementor-posts-container,
    html body [data-id="71c0232"] .elementor-posts-container {
        grid-template-columns: 1fr !important;
    }
}
